import nodemailer from 'nodemailer';
import { describe, expect, it } from 'vitest';
import { ERROR_CODES, SdrError } from '../../src/errors.js';
import {
  createMailTransport,
  renderMailSubject,
  renderMailText,
  sendMail,
  type MailPayload,
  type SmtpSettings,
} from '../../src/publisher/mail.js';

describe('T-017 mail render', () => {
  it('主题含日期与成员名', () => {
    expect(renderMailSubject('张三', '2026-11-25')).toBe('张三 日报 2026-11-25');
  });

  it('纯文本正文不含 HTML 字段', () => {
    const mail = renderMailText({
      displayName: '张三',
      reportDate: '2026-11-25',
      body: '完成接口联调（来源：https://example.com/a）',
    });
    expect(mail.text).toContain('张三');
    expect(mail.text).toContain('完成接口联调');
    expect(mail.text).not.toMatch(/<html|<body/i);
    expect(mail.subject).toBe('张三 日报 2026-11-25');
  });

  it('dry-run 正文与渲染结果逐字一致', () => {
    const body = '进行中优化查询（来源：note 说明）';
    const mail = renderMailText({ displayName: '李四', reportDate: '2026-11-26', body });
    expect(mail.text.endsWith(body)).toBe(true);
  });
});

describe('T-018 sendMail', () => {
  const smtp: SmtpSettings = {
    host: 'smtp.test',
    port: 587,
    user: 'user',
    pass: 'pass',
    from: 'bot@example.com',
  };

  function streamTransport() {
    return createMailTransport(smtp, {
      streamTransport: true,
      newline: 'unix',
      buffer: true,
    });
  }

  it('streamTransport 发送成功返回 messageId', async () => {
    const transport = streamTransport();
    const payload: MailPayload = {
      to: ['dev@example.com'],
      subject: '测试',
      text: 'plain only',
    };
    const result = await sendMail(transport, payload);
    expect(result.ok).toBe(true);
    expect(result.messageId.length).toBeGreaterThan(0);
  });

  it('认证失败映射 SDR-E401', async () => {
    const transport = nodemailer.createTransport({
      host: '127.0.0.1',
      port: 1,
      secure: false,
      auth: { user: 'bad', pass: 'bad' },
      connectionTimeout: 200,
      greetingTimeout: 200,
      socketTimeout: 200,
    });
    await expect(
      sendMail(transport, { to: ['x@y.com'], subject: 's', text: 't' }),
    ).rejects.toMatchObject({ code: ERROR_CODES.SMTP_AUTH_FAILED });
  });

  it('发送结果不包含 html 正文', async () => {
    const transport = streamTransport();
    await sendMail(transport, { to: ['a@b.com'], subject: 's', text: '正文' });
    const sent = transport.sent as nodemailer.SentMessageInfo[];
    const last = sent.at(-1);
    const raw = String(last?.message);
    expect(raw).not.toMatch(/Content-Type: text\/html/i);
  });
});

