describe('T-018 alert', () => {
  const smtp: SmtpSettings = {
    host: 'smtp.test',
    port: 587,
    user: 'user',
    pass: 'pass',
    from: 'bot@example.com',
  };

  function streamTransport(): MailTransport {
    return createMailTransport(smtp, {
      streamTransport: true,
      newline: 'unix',
      buffer: true,
    });
  }

  it('告警正文标注错误码与阶段', () => {
    const text = renderAlertText({
      phase: 'push',
      errorCode: ERROR_CODES.SMTP_AUTH_FAILED,
      message: '认证失败',
      reportDate: '2026-11-25',
    });
    expect(text).toContain(ERROR_CODES.SMTP_AUTH_FAILED);
    expect(text).toContain('push');
    expect(text).toContain('2026-11-25');
  });

  it('sendFailureAlert 经 streamTransport 发出', async () => {
    const transport = streamTransport();
    await sendFailureAlert({
      transport,
      smtp,
      notifyTo: ['ops@example.com'],
      phase: 'collect',
      errorCode: ERROR_CODES.GITHUB_PAGINATION_OVERFLOW,
      message: '分页超限',
      reportDate: '2026-11-25',
    });
    const sent = (transport as { sent?: unknown[] }).sent ?? [];
    expect(sent.length).toBe(1);
  });
});

import { describe, expect, it } from 'vitest';
import { resolveRecipients } from '../../src/publisher/deliver.js';
import type { Member } from '../../src/types.js';

describe('T-018 deliver.resolveRecipients', () => {
  const members: Member[] = [
    {
      id: 1,
      githubLogin: 'a',
      displayName: '甲',
      active: true,
      email: 'a@corp.example',
    },
    {
      id: 2,
      githubLogin: 'b',
      displayName: '乙',
      active: true,
    },
  ];

  it('优先 member.email，缺失时回退环境变量', () => {
    const a = resolveRecipients(members, { memberIds: [1, 2] }, { notifyTo: 'fallback@notify' });
    expect(a.get(1)).toEqual(['a@corp.example']);
    expect(a.get(2)).toEqual(['fallback@notify']);
  });

  it('CLI --to 覆盖默认收件人', () => {
    const map = resolveRecipients(members, { memberIds: [2], cliTo: 'cli@override' }, {});
    expect(map.get(2)).toEqual(['cli@override']);
  });

  it('最后回退 SMTP_FROM', () => {
    const map = resolveRecipients(members, { memberIds: [2] }, { smtpFrom: 'from@smtp' });
    expect(map.get(2)).toEqual(['from@smtp']);
  });
});

import type { Member } from '../types.js';

export interface RecipientEnv {
  readonly notifyTo?: string;
  readonly smtpFrom?: string;
}

export interface RecipientQuery {
  readonly memberIds: readonly number[];
  readonly cliTo?: string;
}

function splitAddresses(raw: string | undefined): string[] {
  if (raw === undefined || raw.trim() === '') return [];
  return raw
    .split(/[,;]/)
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

/** 收件人优先 member.email，回退 SDR_NOTIFY_TO / CLI --to / SMTP_FROM（HANDOVER D-03）。 */
export function resolveRecipients(
  members: readonly Member[],
  query: RecipientQuery,
  env: RecipientEnv,
): Map<number, string[]> {
  const byId = new Map(members.map((m) => [m.id, m]));
  const fallback = splitAddresses(query.cliTo) ||
    splitAddresses(env.notifyTo) ||
    splitAddresses(env.smtpFrom);
  const result = new Map<number, string[]>();

  for (const memberId of query.memberIds) {
    const member = byId.get(memberId);
    const fromEmail = member?.email !== undefined ? splitAddresses(member.email) : [];
  if (fromEmail.length > 0) {
      result.set(memberId, fromEmail);
      continue;
    }
    result.set(memberId, [...fallback]);
  }
  return result;
}

import type { ErrorCode } from '../errors.js';
import {
  renderMailSubject,
  sendMail,
  type MailTransport,
  type SmtpSettings,
} from './mail.js';

export type AlertPhase = 'collect' | 'push';

export interface AlertInput {
  readonly phase: AlertPhase;
  readonly errorCode: ErrorCode;
  readonly message: string;
  readonly reportDate: string;
  readonly source?: string;
}

export function renderAlertText(input: AlertInput): string {
  const lines = [
    `【SDR 告警】阶段=${input.phase}`,
    `日期=${input.reportDate}`,
    `错误码=${input.errorCode}`,
    `说明=${input.message}`,
  ];
  if (input.source !== undefined && input.source !== '') {
    lines.push(`来源=${input.source}`);
  }
  return lines.join('\n');
}

export interface SendFailureAlertOptions extends AlertInput {
  readonly transport: MailTransport;
  readonly smtp: SmtpSettings;
  readonly notifyTo: readonly string[];
}

export async function sendFailureAlert(options: SendFailureAlertOptions): Promise<void> {
  const text = renderAlertText(options);
  const subject = renderMailSubject('运维', `告警 ${options.reportDate}`);
  if (options.notifyTo.length === 0) return;
  await sendMail(options.transport, {
    to: options.notifyTo,
    subject,
    text,
  });
}

import type { Repo } from '../store/repo.js';
import type { SdrConfig } from '../config.js';
import { ERROR_CODES, SdrError } from '../errors.js';
import { sendFailureAlert } from './alert.js';
import { resolveRecipients } from './deliver.js';
import {
  createMailTransport,
  renderMailText,
  sendMail,
  type MailTransport,
} from './mail.js';

export interface PushMemberOptions {
  readonly repo: Repo;
  readonly config: SdrConfig;
  readonly transport?: MailTransport;
  readonly reportDate: string;
  readonly memberId: number;
  readonly displayName: string;
  readonly body: string;
  readonly cliTo?: string;
  readonly dryRun?: boolean;
  readonly notifyTo?: string;
}

export async function pushMemberReport(options: PushMemberOptions): Promise<void> {
  const mail = renderMailText({
    displayName: options.displayName,
    reportDate: options.reportDate,
    body: options.body,
  });

  if (options.dryRun === true) {
    process.stdout.write(`${mail.text}\n`);
    return;
  }

  const smtp = options.config.smtp;
  const transport = options.transport ?? createMailTransport(smtp);
  const recipients = resolveRecipients(
    [options.repo.getMember(options.memberId)!].filter(Boolean) as { id: number; email?: string }[],
    { memberIds: [options.memberId], ...(options.cliTo === undefined ? {} : { cliTo: options.cliTo }) },
    {
      ...(options.notifyTo === undefined ? {} : { notifyTo: options.notifyTo }),
      smtpFrom: smtp.from,
    },
  );
  const to = recipients.get(options.memberId) ?? [];
  if (to.length === 0) {
    throw new SdrError(ERROR_CODES.SMTP_AUTH_FAILED, '无可用收件人');
  }

  const sentAt = new Date();
  try {
    await sendMail(transport, { to, subject: mail.subject, text: mail.text });
    options.repo.insertPushLog({
      reportDate: options.reportDate,
      channel: `member:${options.memberId}`,
      sentAt,
      result: 'ok',
    });
  } catch (error) {
    const code = error instanceof SdrError ? error.code : ERROR_CODES.SMTP_TIMEOUT;
    options.repo.insertPushLog({
      reportDate: options.reportDate,
      channel: `member:${options.memberId}`,
      sentAt,
      result: code,
    });
    const alertTo = resolveRecipients(
      [],
      { memberIds: [] },
      { ...(options.notifyTo === undefined ? {} : { notifyTo: options.notifyTo }), smtpFrom: smtp.from },
    );
    const notify =
      options.notifyTo !== undefined
        ? options.notifyTo
            .split(/[,;]/)
            .map((s) => s.trim())
            .filter(Boolean)
        : [smtp.from];
    await sendFailureAlert({
      transport,
      smtp,
      notifyTo: notify,
      phase: 'push',
      errorCode: code,
      message: error instanceof Error ? error.message : '推送失败',
      reportDate: options.reportDate,
    }).catch(() => undefined);
    throw error;
  }
}

