import { describe, expect, it } from 'vitest';
import { FixedClock } from '../../src/clock.js';
import {
  evaluatePushSchedule,
  hasSuccessfulPush,
  missedPushCatchUpDeadline,
  parsePushTime,
} from '../../src/publisher/scheduler.js';

describe('T-019 scheduler', () => {
  it('到达推送时刻应触发', () => {
    const clock = new FixedClock(new Date('2026-11-25T18:00:00+08:00'));
    const decision = evaluatePushSchedule(clock, '18:00', '2026-11-25', false);
    expect(decision.shouldSend).toBe(true);
    expect(decision.reason).toBe('on_time');
  });

  it('错过时段后 5 分钟内补发', () => {
    const clock = new FixedClock(new Date('2026-11-25T18:04:00+08:00'));
    const decision = evaluatePushSchedule(clock, '18:00', '2026-11-25', false);
    expect(decision.shouldSend).toBe(true);
    expect(decision.reason).toBe('catch_up');
  });

  it('已成功推送则去重', () => {
    const clock = new FixedClock(new Date('2026-11-25T18:01:00+08:00'));
    const decision = evaluatePushSchedule(clock, '18:00', '2026-11-25', true);
    expect(decision.shouldSend).toBe(false);
    expect(decision.reason).toBe('already_sent');
  });

  it('推送时刻前不发送', () => {
    const clock = new FixedClock(new Date('2026-11-25T17:30:00+08:00'));
    const decision = evaluatePushSchedule(clock, '18:00', '2026-11-25', false);
    expect(decision.shouldSend).toBe(false);
    expect(decision.reason).toBe('too_early');
  });

  it('补发截止为推送时刻 +5 分钟', () => {
    const { hour, minute } = parsePushTime('18:00');
    const deadline = missedPushCatchUpDeadline(
      new FixedClock(new Date('2026-11-25T12:00:00+08:00')),
      '2026-11-25',
      hour,
      minute,
    );
    expect(deadline.getTime()).toBe(new Date('2026-11-25T18:05:00+08:00').getTime());
  });

  it('hasSuccessfulPush 识别 push_log 成功记录', () => {
    const logs = [
      { reportDate: '2026-11-25', channel: 'daily', result: 'SDR-E401' },
      { reportDate: '2026-11-25', channel: 'daily', result: 'ok' },
    ];
    expect(hasSuccessfulPush(logs, '2026-11-25', 'daily')).toBe(true);
    expect(hasSuccessfulPush(logs, '2026-11-24', 'daily')).toBe(false);
  });
});

import { dayKey, minutesOfDay, parseInstant } from '../clock.js';
import type { Clock } from '../types.js';

export interface PushLogSlice {
  readonly reportDate: string;
  readonly channel: string;
  readonly result: string;
}

export type ScheduleReason = 'on_time' | 'catch_up' | 'already_sent' | 'too_early' | 'past_window';

export interface ScheduleDecision {
  readonly shouldSend: boolean;
  readonly reason: ScheduleReason;
  readonly retryCount: number;
}

export function parsePushTime(pushTime: string): { hour: number; minute: number } {
  const [hour = '0', minute = '0'] = pushTime.split(':');
  return { hour: Number(hour), minute: Number(minute) };
}

export function missedPushCatchUpDeadline(
  clock: Clock,
  reportDate: string,
  hour: number,
  minute: number,
): Date {
  const [y = 0, m = 1, d = 1] = reportDate.split('-').map(Number);
  const offsetGuess = 8;
  const wallUtc = Date.UTC(y, m - 1, d, hour - offsetGuess, minute + 5, 0);
  const tentative = new Date(wallUtc);
  const localKey = dayKey(clock, tentative);
  if (localKey !== reportDate) {
    return new Date(Date.UTC(y, m - 1, d, hour - offsetGuess, minute + 5, 0));
  }
  const start = parseInstant(`${reportDate}T${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}:00+08:00`);
  return new Date(start.getTime() + 5 * 60_000);
}

function scheduledMinute(hour: number, minute: number): number {
  return hour * 60 + minute;
}

export function hasSuccessfulPush(
  logs: readonly PushLogSlice[],
  reportDate: string,
  channel: string,
): boolean {
  return logs.some(
    (row) => row.reportDate === reportDate && row.channel === channel && row.result === 'ok',
  );
}

export function evaluatePushSchedule(
  clock: Clock,
  pushTime: string,
  reportDate: string,
  alreadySent: boolean,
  channel = 'daily',
): ScheduleDecision {
  if (alreadySent || hasSuccessfulPush([], reportDate, channel)) {
    if (alreadySent) {
      return { shouldSend: false, reason: 'already_sent', retryCount: 0 };
    }
  }
  if (alreadySent) {
    return { shouldSend: false, reason: 'already_sent', retryCount: 0 };
  }

  const today = dayKey(clock, clock.now());
  if (today !== reportDate) {
    return { shouldSend: false, reason: 'too_early', retryCount: 0 };
  }

  const { hour, minute } = parsePushTime(pushTime);
  const target = scheduledMinute(hour, minute);
  const nowMinute = minutesOfDay(clock, clock.now());

  if (nowMinute < target) {
    return { shouldSend: false, reason: 'too_early', retryCount: 0 };
  }

  if (nowMinute === target) {
    return { shouldSend: true, reason: 'on_time', retryCount: 0 };
  }

  const deadline = missedPushCatchUpDeadline(clock, reportDate, hour, minute);
  if (clock.now().getTime() <= deadline.getTime()) {
    return { shouldSend: true, reason: 'catch_up', retryCount: 1 };
  }

  return { shouldSend: false, reason: 'past_window', retryCount: 0 };
}

