export const EXIT = {
  OK: 0,
  UNEXPECTED: 1,
  USAGE: 2,
  PARTIAL: 3,
  ALL_FAILED: 4,
  ENTRY_NOT_FOUND: 6,
  PUSH_FAILED: 7,
  ACCESS_DENIED: 8,
  CONFIG: 9,
  GENERATE: 10,
} as const;

export type ExitCode = (typeof EXIT)[keyof typeof EXIT];

export interface GlobalFlags {
  readonly envFile?: string;
}

export interface ParsedArgv {
  readonly command?: string;
  readonly flags: Map<string, string | true>;
  readonly positionals: string[];
}

export function parseArgv(argv: readonly string[]): ParsedArgv {
  const flags = new Map<string, string | true>();
  const positionals: string[] = [];
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i] ?? '';
    if (token.startsWith('--')) {
      const key = token.slice(2);
      const next = argv[i + 1];
      if (next !== undefined && !next.startsWith('--')) {
        flags.set(key, next);
        i += 1;
      } else {
        flags.set(key, true);
      }
      continue;
    }
    positionals.push(token);
  }
  const command = positionals[0];
  return {
    ...(command === undefined ? {} : { command }),
    flags,
    positionals,
  };
}

export function flagString(flags: Map<string, string | true>, key: string): string | undefined {
  const value = flags.get(key);
  if (value === undefined || value === true) return undefined;
  return value;
}

export function flagBoolean(flags: Map<string, string | true>, key: string): boolean {
  return flags.get(key) === true;
}

import { HistoryAccessDenied, type Repo } from '../store/repo.js';
import { EXIT, type ExitCode } from './exit.js';

export interface HistoryOptions {
  readonly actor: number;
  readonly member: number;
  readonly from: string;
  readonly to: string;
}

export function runHistory(
  repo: Repo,
  options: HistoryOptions,
  write: (text: string) => void = (text) => process.stdout.write(text),
): ExitCode {
  try {
    const rows = repo.findHistory(options.actor, options.member, options.from, options.to);
    for (const item of rows) {
      const header = `${item.report.reportDate} [${item.report.status}]`;
      write(`${header}\n`);
      if (item.report.body !== undefined && item.report.body !== '') {
        write(`${item.report.body}\n`);
      }
      for (const entry of item.entries) {
        write(`- ${entry.timeBlock}/${entry.state}: ${entry.content}\n`);
      }
      write('\n');
    }
    return EXIT.OK;
  } catch (error) {
    if (error instanceof HistoryAccessDenied) return EXIT.ACCESS_DENIED;
    throw error;
  }
}

