import { dayKey } from '../clock.js';
import { sendFailureAlert } from '../publisher/alert.js';
import { createMailTransport } from '../publisher/mail.js';
import type { Repo } from '../store/repo.js';
import type { Clock, Event, Source } from '../types.js';
import { ERROR_CODES, SdrError, type ErrorCode } from '../errors.js';
import type { SdrConfig } from '../config.js';
import { EXIT, type ExitCode } from './exit.js';

export type SourceCollector = () => Promise<Event[]>;

export interface CollectContext {
  readonly repo: Repo;
  readonly clock: Clock;
  readonly config?: SdrConfig;
  readonly notifyTo?: string;
}

export interface CollectOptions {
  readonly date?: string;
  readonly sources: readonly Source[];
  readonly manualText?: string;
  readonly manualRef?: string;
  readonly memberId?: number;
}

function errorCodeOf(error: unknown): ErrorCode {
  if (error instanceof SdrError) return error.code;
  return ERROR_CODES.GITHUB_TOKEN_INVALID;
}

export async function runCollect(
  ctx: CollectContext,
  options: CollectOptions,
  collectors: Partial<Record<Source, SourceCollector>>,
): Promise<ExitCode> {
  const reportDate = options.date ?? dayKey(ctx.clock, ctx.clock.now());
  const runId = `collect-${reportDate}-${ctx.clock.now().getTime()}`;
  const memberId = options.memberId ?? ctx.repo.listActiveMembers()[0]?.id ?? 1;

  const sources = [...options.sources];
  if (options.manualText !== undefined || options.manualRef !== undefined) {
    if (!options.manualText || !options.manualRef) {
      return EXIT.USAGE;
    }
    sources.push('manual');
  }

  if (sources.length === 0) {
    return EXIT.USAGE;
  }

  let failures = 0;
  const transport =
    ctx.config === undefined
      ? undefined
      : createMailTransport(ctx.config.smtp, {
          streamTransport: true,
          newline: 'unix',
          buffer: true,
        });

  for (const source of sources) {
    const startedAt = ctx.clock.now();
    try {
      let events: Event[] = [];
      if (source === 'manual') {
        const fn = collectors.manual;
        if (fn !== undefined) {
          events = await fn();
        } else if (options.manualText && options.manualRef) {
          const { createManualEvent } = await import('../collectors/manual.js');
          events = [
            createManualEvent({
              text: options.manualText,
              ref: options.manualRef,
              memberId,
              runId,
              clock: ctx.clock,
            }),
          ];
        }
      } else {
        const fn = collectors[source];
        if (fn === undefined) {
          throw new SdrError(ERROR_CODES.ENV_MISSING, `未配置采集器：${source}`);
        }
        events = await fn();
      }

      for (const event of events) {
        ctx.repo.upsertEvent(event);
      }
      ctx.repo.insertIngestionRun({
        runId,
        source,
        startedAt,
        finishedAt: ctx.clock.now(),
        result: 'ok',
        eventCount: events.length,
      });
    } catch (error) {
      failures += 1;
      const code = errorCodeOf(error);
      ctx.repo.insertIngestionRun({
        runId,
        source,
        startedAt,
        finishedAt: ctx.clock.now(),
        result: 'failed',
        errorCode: code,
        errorMsg: error instanceof Error ? error.message : '采集失败',
        eventCount: 0,
      });
      if (transport !== undefined && ctx.config !== undefined) {
        const notify =
          ctx.notifyTo
            ?.split(/[,;]/)
            .map((s) => s.trim())
            .filter(Boolean) ?? [ctx.config.smtp.from];
        await sendFailureAlert({
          transport,
          smtp: ctx.config.smtp,
          notifyTo: notify,
          phase: 'collect',
          errorCode: code,
          message: error instanceof Error ? error.message : '采集失败',
          reportDate,
          source,
        }).catch(() => undefined);
      }
    }
  }

  if (failures === 0) return EXIT.OK;
  if (failures === sources.length) return EXIT.ALL_FAILED;
  return EXIT.PARTIAL;
}

import type { KeywordRule, WorkBlock } from '../config.js';
import { assembleReport } from '../generator/report.js';
import type { AttributionContext } from '../generator/attribution.js';
import type { Repo } from '../store/repo.js';
import type { Clock } from '../types.js';
import { EXIT, type ExitCode } from './exit.js';
import { SdrError } from '../errors.js';

export interface GenerateContext {
  readonly repo: Repo;
  readonly clock: Clock;
  readonly rules: readonly KeywordRule[];
  readonly blocks: readonly WorkBlock[];
}

export interface GenerateOptions {
  readonly date: string;
  readonly memberId?: number;
  readonly force?: boolean;
}

function attributionContext(repo: Repo): AttributionContext {
  return {
    findMemberByGithubLogin: (login) => repo.findMemberByGithubLogin(login)?.id,
    findMemberByEmailOrName: (name) => {
      const members = repo.listActiveMembers();
      const hit = members.find(
        (m) => m.displayName.toLowerCase() === name || m.email?.toLowerCase() === name,
      );
      return hit?.id;
    },
    taskWindowMembers: () => [],
  };
}

export function runGenerate(ctx: GenerateContext, options: GenerateOptions): ExitCode {
  const targets =
    options.memberId === undefined
      ? ctx.repo.listActiveMembers()
      : [ctx.repo.getMember(options.memberId)].filter((m) => m !== undefined);

  try {
    for (const member of targets) {
      if (member === undefined) continue;
      const events = ctx.repo.findEventsForDate(member.id ?? 0, options.date);
      assembleReport({
        repo: ctx.repo,
        clock: ctx.clock,
        memberId: member.id ?? 0,
        reportDate: options.date,
        events,
        rules: ctx.rules,
        blocks: ctx.blocks,
        attributionCtx: attributionContext(ctx.repo),
        ...(options.force === true ? { force: true } : {}),
      });
    }
    return EXIT.OK;
  } catch (error) {
    if (error instanceof SdrError && error.code.startsWith('SDR-E6')) {
      return EXIT.GENERATE;
    }
    throw error;
  }
}

import type { Repo } from '../store/repo.js';
import { EXIT, type ExitCode } from './exit.js';

export interface EditOptions {
  readonly date: string;
  readonly memberId: number;
  readonly addText?: string;
  readonly addRef?: string;
  readonly removeEntry?: number;
  readonly acceptAttribution?: boolean;
  readonly acceptAll?: boolean;
  readonly timeBlock?: string;
}

export function runEdit(repo: Repo, options: EditOptions): ExitCode {
  const report = repo.findReport(options.memberId, options.date);
  if (report?.id === undefined && options.removeEntry === undefined && !options.acceptAttribution) {
    return EXIT.ENTRY_NOT_FOUND;
  }

  if (options.removeEntry !== undefined) {
    const ok = repo.removeEntryById(options.removeEntry);
    return ok ? EXIT.OK : EXIT.ENTRY_NOT_FOUND;
  }

  if (options.addText !== undefined) {
    if (!options.addRef) return EXIT.USAGE;
    try {
      repo.addManualTextEntry(
        options.memberId,
        options.date,
        options.addText,
        options.addRef,
        options.timeBlock ?? 'afternoon',
      );
      return EXIT.OK;
    } catch {
      return EXIT.ENTRY_NOT_FOUND;
    }
  }

  if (options.acceptAttribution === true && report?.id !== undefined) {
    repo.acceptAttribution(report.id, options.acceptAll === true);
    return EXIT.OK;
  }

  return EXIT.USAGE;
}

import type { SdrConfig } from '../config.js';
import { dayKey } from '../clock.js';
import { evaluatePushSchedule } from '../publisher/scheduler.js';
import type { Clock } from '../types.js';
import type { Repo } from '../store/repo.js';
import { runPush, type PushContext } from './push.js';

export interface ServeOptions {
  readonly tickMs?: number;
  readonly onTick?: (date: string) => Promise<void>;
}

export function startServeLoop(
  ctx: PushContext,
  options: ServeOptions = {},
): { stop: () => void } {
  const tickMs = options.tickMs ?? 30_000;
  let stopped = false;

  const tick = async () => {
    if (stopped) return;
    const date = dayKey(ctx.clock, ctx.clock.now());
    const alreadySent = ctx.repo.hasPushLogOk(date, 'daily');
    const decision = evaluatePushSchedule(ctx.clock, ctx.config.pushTime, date, alreadySent);
    if (decision.shouldSend) {
      await runPush(ctx, { date, forceSchedule: true });
      if (options.onTick) await options.onTick(date);
    }
  };

  const timer = setInterval(() => {
    void tick();
  }, tickMs);
  void tick();

  return {
    stop: () => {
      stopped = true;
      clearInterval(timer);
    },
  };
}

export function createServeContext(
  repo: Repo,
  clock: Clock,
  config: SdrConfig,
  notifyTo?: string,
): PushContext {
  return { repo, clock, config, ...(notifyTo === undefined ? {} : { notifyTo }) };
}

import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { dayKey, systemClock } from '../clock.js';
import { loadConfig, loadKeywordRules, loadWorkBlocks } from '../config.js';
import { applyEnvFile } from '../env-file.js';
import { exitCode, SdrError } from '../errors.js';
import { collectFeishu } from '../collectors/feishu.js';
import { collectGithub } from '../collectors/github.js';
import { collectLocal } from '../collectors/local.js';
import { dayWindow } from '../clock.js';
import { createHttpClient } from '../http.js';
import { createRepo } from '../store/repo.js';
import { openDatabase } from '../store/db.js';
import { flagBoolean, flagString, parseArgv } from './argv.js';
import { runCollect } from './collect.js';
import { runEdit } from './edit.js';
import { runGenerate } from './generate.js';
import { runHistory } from './history.js';
import { runPush } from './push.js';
import { createServeContext, startServeLoop } from './serve.js';
import { EXIT, type ExitCode } from './exit.js';

const configDir = join(dirname(fileURLToPath(import.meta.url)), '../../config');

function envWithDotenv(): Record<string, string | undefined> {
  const root = join(dirname(fileURLToPath(import.meta.url)), '../..');
  return applyEnvFile(join(root, '.env'), { ...process.env });
}

export async function runCli(argv: readonly string[]): Promise<ExitCode> {
  const parsed = parseArgv(argv);
  const command = parsed.command;
  if (command === undefined) {
    process.stderr.write('用法：sdr <collect|generate|edit|push|history|serve> [options]\n');
    return EXIT.USAGE;
  }

  const envPath = flagString(parsed.flags, 'env-file') ?? join(dirname(fileURLToPath(import.meta.url)), '../..', '.env');
  const env = applyEnvFile(envPath, { ...process.env });
  const notifyTo = env.SDR_NOTIFY_TO;

  let config;
  let db;
  let repo;
  const clock = systemClock;

  try {
    config = loadConfig(env);
    db = openDatabase(config.dbPath);
    repo = createRepo(db, clock);
  } catch (error) {
    if (error instanceof SdrError && error.code.startsWith('SDR-E3')) {
      return EXIT.CONFIG;
    }
    throw error;
  }

  const rules = loadKeywordRules(join(configDir, 'keywords.yaml'));
  const blocks = loadWorkBlocks(join(configDir, 'work-hours.yaml'));

  const date = flagString(parsed.flags, 'date') ?? dayKey(clock, clock.now());

  switch (command) {
    case 'collect': {
      const sources = parsed.flags.getAll?.('source') as never;
      const sourceList = [...parsed.flags.entries()]
        .filter(([key]) => key === 'source')
        .map(([, value]) => String(value)) as (
        | 'github'
        | 'feishu'
        | 'local'
        | 'manual'
      )[];
      const selected =
        sourceList.length > 0
          ? sourceList
          : (['github', 'feishu', 'local'] as const);
      const member = repo.listActiveMembers()[0];
      const memberId = member?.id ?? 1;
      const { since, until } = dayWindow(clock, date);
      const runId = `cli-collect-${date}`;
      const http = createHttpClient();
      const githubRepo = env.SDR_GITHUB_REPO ?? 'acme/sdr';
      const localRoot = env.SDR_LOCAL_ROOT ?? process.cwd();
      const tokenPath = env.SDR_FEISHU_TOKEN_PATH;

      let feishuToken = '';
      if (tokenPath) {
        const { readFileSync } = await import('node:fs');
        try {
          const raw = JSON.parse(readFileSync(tokenPath, 'utf8')) as { access_token?: string };
          feishuToken = raw.access_token ?? '';
        } catch {
          feishuToken = '';
        }
      }

      return runCollect(
        { repo, clock, config, ...(notifyTo === undefined ? {} : { notifyTo }) },
        {
          date,
          sources: [...selected],
          ...(flagString(parsed.flags, 'manual') === undefined
            ? {}
            : { manualText: flagString(parsed.flags, 'manual') }),
          ...(flagString(parsed.flags, 'ref') === undefined
            ? {}
            : { manualRef: flagString(parsed.flags, 'ref') }),
          memberId,
        },
        {
          github: () =>
            collectGithub({
              repo: githubRepo,
              since,
              until,
              token: config.github.token,
              clock,
              memberId,
              runId,
              http,
            }),
          feishu: () =>
            collectFeishu({
              since,
              until,
              token: feishuToken || config.feishu.appSecret,
              clock,
              memberId,
              runId,
              http,
            }),
          local: () =>
            collectLocal({ rootDir: localRoot, since, until, clock, memberId, runId }),
        },
      );
    }
    case 'generate': {
      const memberRaw = flagString(parsed.flags, 'member');
      return runGenerate(
        { repo, clock, rules, blocks },
        {
          date,
          ...(memberRaw === undefined ? {} : { memberId: Number(memberRaw) }),
          ...(flagBoolean(parsed.flags, 'force') ? { force: true } : {}),
        },
      );
    }
    case 'edit': {
      const memberRaw = flagString(parsed.flags, 'member');
      if (memberRaw === undefined) return EXIT.USAGE;
      const removeRaw = flagString(parsed.flags, 'remove-entry');
      return runEdit(repo, {
        date,
        memberId: Number(memberRaw),
        ...(flagString(parsed.flags, 'add-text') === undefined
          ? {}
          : { addText: flagString(parsed.flags, 'add-text') }),
        ...(flagString(parsed.flags, 'ref') === undefined
          ? {}
          : { addRef: flagString(parsed.flags, 'ref') }),
        ...(removeRaw === undefined ? {} : { removeEntry: Number(removeRaw) }),
        ...(flagBoolean(parsed.flags, 'accept-attribution')
          ? { acceptAttribution: true, ...(flagBoolean(parsed.flags, 'all') ? { acceptAll: true } : {}) }
          : {}),
      });
    }
    case 'push': {
      return runPush(
        {
          repo,
          clock,
          config,
          ...(notifyTo === undefined ? {} : { notifyTo }),
        },
        {
          date,
          ...(flagBoolean(parsed.flags, 'dry-run') ? { dryRun: true } : {}),
          ...(flagString(parsed.flags, 'to') === undefined
            ? {}
            : { to: flagString(parsed.flags, 'to') }),
        },
      );
    }
    case 'history': {
      const memberRaw = flagString(parsed.flags, 'member');
      const from = flagString(parsed.flags, 'from');
      const to = flagString(parsed.flags, 'to');
      const actorRaw = flagString(parsed.flags, 'actor') ?? memberRaw;
      if (memberRaw === undefined || from === undefined || to === undefined || actorRaw === undefined) {
        return EXIT.USAGE;
      }
      return runHistory(repo, {
        actor: Number(actorRaw),
        member: Number(memberRaw),
        from,
        to,
      });
    }
    case 'serve': {
      const handle = startServeLoop(
        createServeContext(repo, clock, config, notifyTo),
        { tickMs: 30_000 },
      );
      await new Promise<void>((resolve) => {
        process.on('SIGINT', () => {
          handle.stop();
          resolve();
        });
      });
      return EXIT.OK;
    }
    default:
      return EXIT.USAGE;
  }
}

export async function cliMain(argv: readonly string[]): Promise<void> {
  try {
    const code = await runCli(argv);
    process.exitCode = code;
  } catch (error) {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
    process.exitCode = error instanceof SdrError ? exitCode(error) : EXIT.UNEXPECTED;
  }
}

